'use strict';

const STORAGE_KEY = 'todos-vanillajs';
const ENTER_KEY = 13;

const $todoInput = document.querySelector('.new-todo');
const $main = document.querySelector('.main');
const $footer = document.querySelector('.footer');
const $list = document.querySelector('.todo-list');
const $toggleAll = document.querySelector('#toggle-all');
const $clearCompleted = document.querySelector('.clear-completed');
const $count = document.querySelector('.todo-count');
const $filters = document.querySelector('.filters');

let todos = [];
let editingId = null;

/**
 * Reads the persisted todo list from localStorage.
 * @planks("the app is loaded with no todos")
 * @planks("the app is loaded with todos:")
 * @planks("the app has {int} active todos")
 * @planks("the user reloads the app")
 * @planks("^the todo list has (\d+) items?$")
 * @planks-provisional("features/@captain-persistence-edge.feature:Corrupt localStorage JSON loads as an empty list")
 */
function loadTodos() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    todos = Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    todos = [];
  }
}

/**
 * Persists the current todo list to localStorage.
 * @planks("the {string} localStorage entry is a JSON array")
 * @planks("^each stored todo has the fields (.+)$")
 */
function saveTodos() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
}

/**
 * Generates a unique id for a new todo (preserved as the persisted `id` field).
 * @planks("^each stored todo has the fields (.+)$")
 */
function uuid() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

/**
 * Resolves the active route filter from the location hash.
 * @planks("the user opens the {string} filter")
 * @planks("the {string} filter link is selected")
 * @planks("the {string} filter link is not selected")
 */
function getFilter() {
  const hash = (location.hash || '').replace(/^#\/?/, '');
  if (hash === 'active') return 'active';
  if (hash === 'completed') return 'completed';
  return 'all';
}

/**
 * Creates a new todo from a trimmed, non-empty title.
 * @planks("the user types {string} into the new todo input")
 * @planks("the user presses Enter")
 */
function createTodo(title) {
  const trimmed = (title || '').trim();
  if (trimmed === '') return;
  todos.push({ id: uuid(), title: trimmed, completed: false });
  saveTodos();
  render();
}

/**
 * Toggles a single todo's completed state by id.
 * @planks("the user toggles the todo {string}")
 * @planks("the todo {string} is marked completed")
 */
function toggleTodo(id, completed) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) return;
  todo.completed = completed;
  saveTodos();
  render();
}

/**
 * Sets every todo to the same completed state.
 * @planks("the user marks all todos as complete")
 */
function toggleAll(completed) {
  todos.forEach((t) => {
    t.completed = completed;
  });
  saveTodos();
  render();
}

/**
 * Removes completed todos from the model.
 * @planks("the user clears completed todos")
 */
function clearCompleted() {
  todos = todos.filter((t) => !t.completed);
  saveTodos();
  render();
}

/**
 * Commits an edited title, or discards the edit when requested.
 * @planks("the user double-clicks the todo {string}")
 * @planks("the user edits the title to {string} and presses Enter")
 * @planks("the user edits the title to {string} and blurs the field")
 * @planks("the user edits the title to {string} and presses Escape")
 * @planks("the todo {string} is in edit mode")
 * @planks("the todo {string} is not in edit mode")
 */
function commitEdit(id, value, discard) {
  const todo = todos.find((t) => t.id === id);
  if (!todo) return;
  editingId = null;
  if (discard) {
    render();
    return;
  }
  const trimmed = (value || '').trim();
  if (trimmed === '') {
    todos = todos.filter((t) => t.id !== id);
  } else {
    todo.title = trimmed;
  }
  saveTodos();
  render();
}

/**
 * Builds a list row element for a todo, wiring its event handlers once.
 * Rows are created once and then kept in place across renders, keyed by todo id.
 */
function createRow(todo) {
  const li = document.createElement('li');
  li.dataset.id = todo.id;

  const view = document.createElement('div');
  view.className = 'view';
  const toggle = document.createElement('input');
  toggle.className = 'toggle';
  toggle.type = 'checkbox';
  const label = document.createElement('label');
  const destroy = document.createElement('button');
  destroy.className = 'destroy';
  view.appendChild(toggle);
  view.appendChild(label);
  view.appendChild(destroy);

  const edit = document.createElement('input');
  edit.className = 'edit';

  li.appendChild(view);
  li.appendChild(edit);

  toggle.addEventListener('change', () => toggleTodo(todo.id, toggle.checked));
  label.addEventListener('dblclick', () => {
    editingId = todo.id;
    li.classList.add('editing');
    edit.value = todo.title;
    edit.focus();
  });
  destroy.addEventListener('click', () => {
    todos = todos.filter((t) => t.id !== todo.id);
    saveTodos();
    render();
  });
  edit.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
      commitEdit(todo.id, edit.value, false);
    } else if (e.key === 'Escape') {
      commitEdit(todo.id, edit.value, true);
    }
  });
  edit.addEventListener('blur', () => commitEdit(todo.id, edit.value, false));

  return li;
}

/**
 * Syncs an existing row element to the current model and route state.
 * The row element itself is preserved; only its contents and state change.
 */
function updateRow(li, todo, filter) {
  li.classList.toggle('completed', todo.completed);
  li.classList.toggle('editing', editingId === todo.id);
  li.querySelector('.toggle').checked = todo.completed;
  li.querySelector('label').textContent = todo.title;
  if (editingId !== todo.id) {
    li.querySelector('.edit').value = todo.title;
  }
  if (filter === 'active' && todo.completed) li.hidden = true;
  else if (filter === 'completed' && !todo.completed) li.hidden = true;
  else li.hidden = false;
}

/**
 * Renders the list and chrome from the current model and route.
 * @planks("the todo list shows {string}")
 * @planks("the todo list does not show {string}")
 * @planks("^the todo list has (\d+) items?$")
 * @planks("the main section is hidden")
 * @planks("the footer is hidden")
 * @planks("the remaining count reads {string}")
 * @planks("the clear-completed button is hidden")
 * @planks("the clear-completed button is visible")
 * @planks("the mark-all control is checked")
 * @planks("the mark-all control is unchecked")
 * @planks("every todo is marked completed")
 * @planks-provisional("features/@captain-deleting-todos.feature:Deleting a todo removes it from the list")
 * @planks-provisional("features/@captain-list-state.feature:Mark-all control is indeterminate when only some todos are complete")
 */
function render() {
  const filter = getFilter();
  const seen = new Set();
  todos.forEach((todo) => {
    let li = $list.querySelector('li[data-id="' + String(todo.id) + '"]');
    if (!li) {
      li = createRow(todo);
      $list.appendChild(li);
    }
    updateRow(li, todo, filter);
    seen.add(String(todo.id));
  });
  Array.prototype.forEach.call($list.querySelectorAll('li'), (li) => {
    if (!seen.has(li.dataset.id)) li.remove();
  });

  const hasTodos = todos.length > 0;
  if (hasTodos) {
    $main.removeAttribute('hidden');
    $footer.removeAttribute('hidden');
  } else {
    $main.setAttribute('hidden', '');
    $footer.setAttribute('hidden', '');
  }

  const active = todos.filter((t) => !t.completed).length;
  const word = active === 1 ? 'item' : 'items';
  $count.innerHTML = '<strong>' + active + '</strong> ' + word + ' left';

  const completedCount = todos.filter((t) => t.completed).length;
  if (completedCount > 0) $clearCompleted.removeAttribute('hidden');
  else $clearCompleted.setAttribute('hidden', '');

  $toggleAll.checked = hasTodos && active === 0;
  $toggleAll.indeterminate = active > 0 && active < todos.length;

  const current = getFilter();
  Array.prototype.forEach.call($filters.querySelectorAll('a'), (a) => {
    const href = (a.getAttribute('href') || '').replace(/^#\/?/, '');
    const f = href === '' ? 'all' : href;
    if (f === current) a.classList.add('selected');
    else a.classList.remove('selected');
  });
}

/**
 * Applies the active route filter and updates the selected link.
 * @planks("the user opens the {string} filter")
 * @planks("the {string} filter link is selected")
 * @planks("the {string} filter link is not selected")
 */
function applyFilter() {
  render();
}

/** @planks("the new todo input is empty") */
$todoInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' || e.keyCode === ENTER_KEY) {
    createTodo($todoInput.value);
    $todoInput.value = '';
  }
});

$toggleAll.addEventListener('change', () => toggleAll($toggleAll.checked));
$clearCompleted.addEventListener('click', clearCompleted);
window.addEventListener('hashchange', applyFilter);

loadTodos();
/** @planks("the new todo input is focused") */
$todoInput.focus();
render();

import { Given, When, Then } from '@cucumber/cucumber';

// ----- Background / loading -----

Given('the app is loaded with no todos', function () {
  this.loadApp(null);
});

Given('the app is loaded with todos:', function (dataTable) {
  const rows = dataTable.hashes();
  const todos = rows.map((r, i) => ({
    id: i + 1,
    title: r.title,
    completed: r.completed === 'true',
  }));
  this.loadApp(todos);
});

Given('the app has {int} active todos', function (count) {
  const todos = [];
  for (let i = 0; i < count; i++) {
    todos.push({ id: i + 1, title: `Todo ${i + 1}`, completed: false });
  }
  this.loadApp(todos);
});

// ----- Creating todos -----

When('the user types {string} into the new todo input', function (text) {
  const input = this.newTodoInput();
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the user presses Enter', function () {
  const input = this.newTodoInput();
  input.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }),
  );
});

Then('the todo list shows {string}', function (title) {
  if (!this.todoVisible(title)) {
    throw new Error(`Todo list does not show "${title}"`);
  }
});

Then('the todo list does not show {string}', function (title) {
  if (this.todoVisible(title)) {
    throw new Error(`Todo list shows "${title}" but should not`);
  }
});

Then(/^the todo list has (\d+) items?$/, function (n) {
  const count = parseInt(n, 10);
  const found = this.todoItems().length;
  if (found !== count) {
    throw new Error(`Expected ${count} item(s), found ${found}`);
  }
});

Then('the new todo input is empty', function () {
  const input = this.newTodoInput();
  if (input.value !== '') {
    throw new Error(`New todo input is not empty: "${input.value}"`);
  }
});

Then('the new todo input is focused', function () {
  if (this.document.activeElement !== this.newTodoInput()) {
    throw new Error('New todo input is not focused');
  }
});

// ----- Completing todos -----

Given('the todo {string} is marked completed', function (title) {
  // The spec reuses this phrase as both a Given precondition (ensure the todo is
  // completed) and a Then assertion. Implemented as the real UI action that drives
  // the todo to the completed state; on the success path of a Then this is a no-op
  // and the subsequent assertion holds.
  let li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  const toggle = li.querySelector('.toggle');
  if (!toggle.checked) {
    toggle.checked = true;
    toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    li = this.liByTitle(title); // re-query: the app re-renders on change
  }
  if (!li || !li.classList.contains('completed')) {
    throw new Error(`Todo "${title}" not marked completed`);
  }
});

When('the user toggles the todo {string}', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  this._rowsBefore = { [title]: li };
  const toggle = li.querySelector('.toggle');
  toggle.checked = !toggle.checked;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user marks all todos as complete', function () {
  this._rowsBefore = {};
  for (const li of this.todoItems()) {
    const lbl = li.querySelector('label')?.textContent?.trim();
    if (lbl) this._rowsBefore[lbl] = li;
  }
  const mark = this.document.querySelector('#toggle-all');
  mark.checked = true;
  mark.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

Then('every todo is marked completed', function () {
  const items = this.todoItems();
  if (items.length === 0) throw new Error('No todos to check');
  for (const li of items) {
    if (!li.classList.contains('completed')) {
      throw new Error(`Todo "${li.querySelector('label').textContent}" not completed`);
    }
  }
});

Then('the row for {string} is the same DOM element as before the last change', function (title) {
  const before = this._rowsBefore && this._rowsBefore[title];
  if (!before) throw new Error(`No captured row for "${title}" before the last change`);
  const after = this.liByTitle(title);
  if (!after) throw new Error(`Row "${title}" is not present after the change`);
  if (after !== before) {
    throw new Error(`Row "${title}" was rebuilt instead of updated in place`);
  }
});

Then('the checkbox for {string} is hidden', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  const display = this.window.getComputedStyle(li.querySelector('.toggle')).display;
  if (display !== 'none') {
    throw new Error(`Checkbox for "${title}" is not hidden (display: ${display})`);
  }
});

Then('the delete button for {string} is hidden', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  const display = this.window.getComputedStyle(li.querySelector('.destroy')).display;
  if (display !== 'none') {
    throw new Error(`Delete button for "${title}" is not hidden (display: ${display})`);
  }
});

Then('the label for {string} is hidden', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  const display = this.window.getComputedStyle(li.querySelector('label')).display;
  if (display !== 'none') {
    throw new Error(`Label for "${title}" is not hidden (display: ${display})`);
  }
});

Then('the mark-all control is checked', function () {
  const mark = this.document.querySelector('#toggle-all');
  if (!mark.checked) throw new Error('Mark-all control is not checked');
});

Then('the mark-all control is unchecked', function () {
  const mark = this.document.querySelector('#toggle-all');
  if (mark.checked) throw new Error('Mark-all control is checked');
});

When('the user clears completed todos', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.dispatchEvent(new this.window.Event('click', { bubbles: true }));
});

// ----- Editing todos -----

When('the user double-clicks the todo {string}', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  li.querySelector('label').dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

Then('the todo {string} is in edit mode', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  if (!li.classList.contains('editing')) {
    throw new Error(`Todo "${title}" not in edit mode`);
  }
});

Then('the todo {string} is not in edit mode', function (title) {
  const li = this.liByTitle(title);
  if (!li) throw new Error(`No todo "${title}"`);
  if (li.classList.contains('editing')) {
    throw new Error(`Todo "${title}" still in edit mode`);
  }
});

When('the user edits the title to {string} and presses Enter', function (text) {
  const li = this.document.querySelector('.todo-list li.editing');
  if (!li) throw new Error('No todo in edit mode');
  const edit = li.querySelector('.edit');
  edit.value = text;
  edit.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }),
  );
});

When('the user edits the title to {string} and blurs the field', function (text) {
  const li = this.document.querySelector('.todo-list li.editing');
  if (!li) throw new Error('No todo in edit mode');
  const edit = li.querySelector('.edit');
  edit.value = text;
  edit.dispatchEvent(new this.window.Event('blur'));
});

When('the user edits the title to {string} and presses Escape', function (text) {
  const li = this.document.querySelector('.todo-list li.editing');
  if (!li) throw new Error('No todo in edit mode');
  const edit = li.querySelector('.edit');
  edit.value = text;
  edit.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }),
  );
});

// ----- List summary and visibility -----

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  if (!main.hasAttribute('hidden')) throw new Error('Main section is not hidden');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  if (!footer.hasAttribute('hidden')) throw new Error('Footer is not hidden');
});

Then('the page contains a new todo input', function () {
  if (!this.newTodoInput()) throw new Error('No new todo input present');
});

Then('the page contains a toggle-all control', function () {
  if (!this.document.querySelector('#toggle-all')) throw new Error('No toggle-all control present');
});

Then(
  'the page contains {string}, {string}, and {string} filter links',
  function (a, b, c) {
    const want = [a, b, c];
    const links = Array.from(this.document.querySelectorAll('.filters a'));
    for (const t of want) {
      if (!links.some((l) => l.textContent.trim() === t)) {
        throw new Error(`No filter link "${t}" present`);
      }
    }
  },
);

Then('the remaining count reads {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  const actual = count.textContent.replace(/\s+/g, ' ').trim();
  if (actual !== text) {
    throw new Error(`Remaining count reads "${actual}", expected "${text}"`);
  }
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn.hasAttribute('hidden')) throw new Error('Clear-completed button is not hidden');
});

Then('the clear-completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn.hasAttribute('hidden')) throw new Error('Clear-completed button is hidden');
});

// ----- Persistence -----

When('the user reloads the app', function () {
  this.reloadApp();
});

Then('the {string} localStorage entry is a JSON array', function (key) {
  const raw = this.window.localStorage.getItem(key);
  if (raw == null) throw new Error(`localStorage key "${key}" missing`);
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(`"${key}" is not valid JSON: ${e.message}`);
  }
  if (!Array.isArray(parsed)) throw new Error(`"${key}" is not a JSON array`);
});

Then(/^each stored todo has the fields (.+)$/, function (fieldsRaw) {
  const fields = (fieldsRaw.match(/"([^"]+)"/g) || []).map((s) => s.slice(1, -1));
  const raw = this.window.localStorage.getItem('todos-vanillajs');
  const parsed = JSON.parse(raw);
  for (const todo of parsed) {
    for (const f of fields) {
      if (!(f in todo)) {
        throw new Error(`Stored todo missing field "${f}": ${JSON.stringify(todo)}`);
      }
    }
  }
});

// ----- Routing and filters -----

When('the user opens the {string} filter', function (name) {
  const map = { All: '#/', Active: '#/active', Completed: '#/completed' };
  const hash = map[name] || '#/';
  this.window.location.hash = hash;
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

Then('the {string} filter link is selected', function (name) {
  const link = this.filterLink(name);
  if (!link) throw new Error(`No filter link "${name}"`);
  if (!link.classList.contains('selected')) {
    throw new Error(`Filter link "${name}" is not selected`);
  }
});

Then('the {string} filter link is not selected', function (name) {
  const link = this.filterLink(name);
  if (!link) throw new Error(`No filter link "${name}"`);
  if (link.classList.contains('selected')) {
    throw new Error(`Filter link "${name}" is selected`);
  }
});

